use super::*;
use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering::Relaxed};
use serde_json::{json,Value as J};
fn plan(schema:&str, extra:&[(&str,&str)]) -> Plan {
 let proof=Document::parse(r#"{"openbindings":"0.2.0","operations":{"op":{"input":{"$ref":"https://review.test/root"}}}}"#).unwrap().validate().unwrap().conformant().unwrap();
 let mut rs=vec![ExternalSchema{uri:"https://review.test/root".into(),document:JsonValue::parse(schema).unwrap()}];rs.extend(extra.iter().map(|(u,s)|ExternalSchema{uri:(*u).into(),document:JsonValue::parse(s).unwrap()}));
 let ext=ExternalSchemas::new(rs).unwrap();let c=AtomicBool::new(false);let p=PreparationLimits::default();let env=proof.operation("op").unwrap().input().unwrap().environment(&ext,&p,&c).unwrap();
 openbindings_internal_schema::preparation::Attempt::run(p.max_sdk_work_units,p.max_sdk_reservation_bytes,&c,|a|Plan::new(env,Limits::default(),p,a)).unwrap().unwrap()
}
fn observed(o:ValueOutcome)->String {match o {ValueOutcome::Satisfies=>"S".into(),ValueOutcome::Fails{..}=>"F".into(),ValueOutcome::Undefined{..}=>"U".into(),ValueOutcome::NoVerdict{detail}=>format!("N:{:?}",detail.reason)}}
fn check(schema:&str,value:&str,expected:&str){let p=plan(schema,&[]);let v=JsonValue::parse(value).unwrap();for d in [Detail::Outcome,Detail::Explain]{assert_eq!(observed(p.evaluate(&v,d,&AtomicBool::new(false))),expected,"schema={schema}, value={value}");}}
fn run<'a>(p:&'a Plan,c:&'a dyn WorkControl)->Run<'a>{Run{plan:p,record_witnesses:false,graph:Graph::new(48<<20,None,64,c),atoms:Vec::new(),values:values::Values::default(),effects:HashMap::new(),active:storage::Entries::default(),alias_path:storage::Entries::default(),empty_context:Arc::new(Vec::new()),opaque_cycles:HashSet::new(),pending_cycles:HashSet::new(),cuts:HashSet::new(),provisional:HashSet::new(),memo:HashMap::new(),facts:HashMap::new(),pending_facts:HashMap::new(),supports:HashMap::new(),support_memo_count:0,patterns:storage::Entries::default()}}
fn chain(n:usize)->String {let mut defs=serde_json::Map::new();for i in 0..n {defs.insert(format!("n{i}"),if i+1==n {json!({"type":"integer"})}else{json!({"$ref":format!("#/$defs/n{}",i+1)})});}json!({"$defs":defs,"$ref":"#/$defs/n0"}).to_string()}
struct Stop{n:AtomicUsize,at:usize}
impl WorkControl for Stop{fn is_cancelled(&self)->bool{self.n.fetch_add(1,Relaxed)>=self.at}}
#[test] fn a1_repeated_shared_alias(){let s=r##"{"$defs":{"A":{"$ref":"#/$defs/B"},"B":{"type":"integer"}},"allOf":[{"$ref":"#/$defs/A"},{"$ref":"#/$defs/A"}]}"##;check(s,"1","S");check(s,r#""x""#,"F");}
#[test] fn a2_long_then_short_reverse_and_no_allocations(){let p=plan(&chain(128),&[]);let c=AtomicBool::new(false);let mut r=run(&p,&c);let ctx=r.empty_context.clone();let (leaf,_,cycle)=r.alias(p.entry,&ctx).unwrap();assert!(!cycle);assert_eq!(r.alias_path.len(),0);let short=p.queries.keys().find_map(|(node,_)| {let v=&p.environment.space().node(*node).value; (v.get("$ref").and_then(|v|v.as_str())==Some("#/$defs/n127")).then_some(*node)}).unwrap();
 let snap=crate::review_allocations::start();let before=r.graph.remaining();for _ in 0..1000 {assert_eq!(r.alias(short,&ctx).unwrap().0,leaf);assert_eq!(r.alias_path.len(),0);}let after=r.graph.remaining();let m=crate::review_allocations::finish(snap,1000);assert_eq!(m["allocations_per_op"],0.0);assert_eq!(before.bytes,after.bytes);println!("scratch-alias-warm={m}");
 assert_eq!(r.alias(p.entry,&ctx).unwrap().0,leaf);assert_eq!(r.alias_path.len(),0);
 let mut r2=run(&p,&c);assert_eq!(r2.alias(short,&ctx).unwrap().0,leaf);assert_eq!(r2.alias(p.entry,&ctx).unwrap().0,leaf);assert_eq!(r2.alias(short,&ctx).unwrap().0,leaf);
}
#[test] fn a3_consuming_alias_to_leaf(){let s=r##"{"$defs":{"A":{"$ref":"#/$defs/B"},"B":{"type":"integer"}},"items":{"$ref":"#/$defs/A"}}"##;let a=vec![json!(1);20000];check(s,&json!(a).to_string(),"S");let mut a=a;a.push(json!("late"));check(s,&json!(a).to_string(),"F");}
#[test] fn a4_cycles_after_other_aliases(){for defs in [r##"{"A":{"$ref":"#/$defs/A"},"B":{"type":"integer"}}"##,r##"{"A":{"$ref":"#/$defs/C"},"C":{"$ref":"#/$defs/A"},"B":{"type":"integer"}}"##] {let defs:J=serde_json::from_str(defs).unwrap();for(op,arms,expect)in[("allOf",json!([{"$ref":"#/$defs/B"},{"$ref":"#/$defs/A"},{"$ref":"#/$defs/B"}]),"U"),("anyOf",json!([{"$ref":"#/$defs/B"},{"$ref":"#/$defs/A"}]),"S"),("allOf",json!([false,{"$ref":"#/$defs/A"}]),"F")] {check(&json!({"$defs":defs,op:arms}).to_string(),"1",expect);}}}
#[test] fn a5_inherited_effective_scope(){let rows:J=serde_json::from_str(include_str!("execution/tests/controls.json")).unwrap();let mut count=0;for row in rows["rows"].as_array().unwrap(){if !row["id"].as_str().unwrap().contains("binding")&&!row["id"].as_str().unwrap().contains("scope"){continue}let owned:Vec<_>=row["resources"].as_object().map(|m|m.iter().map(|(u,s)|(u.as_str(),s.as_str().unwrap())).collect()).unwrap_or_default();let p=plan(row["schema"].as_str().unwrap(),&owned);let v=JsonValue::parse(row["value"].as_str().unwrap()).unwrap();for d in[Detail::Outcome,Detail::Explain]{assert_eq!(observed(p.evaluate(&v,d,&AtomicBool::new(false))),row["required"].as_str().unwrap(),"{}",row["id"]);}count+=1;}assert_eq!(count,6);}
#[test] fn a5_recursive_2019_scope() { let base=r##"{"$schema":"https://json-schema.org/draft/2019-09/schema","$id":"https://review.test/base","$recursiveAnchor":true,"type":"object","properties":{"next":{"$recursiveRef":"#"}}}"##;let p=plan(r##"{"$schema":"https://json-schema.org/draft/2019-09/schema","$recursiveAnchor":true,"$ref":"https://review.test/base","required":["tag"]}"##,&[("https://review.test/base",base)]);for(value,required)in[(r#"{"tag":1,"next":{"tag":1}}"#,"S"),(r#"{"tag":1,"next":{}}"#,"F")]{let v=JsonValue::parse(value).unwrap();for d in[Detail::Outcome,Detail::Explain]{assert_eq!(observed(p.evaluate(&v,d,&AtomicBool::new(false))),required);}}}
#[test] fn a6_all_alias_exits_restore_scratch(){for schema in [chain(40),r##"{"$defs":{"A":{"$ref":"#/$defs/B"},"B":{"$ref":"#/$defs/A"}},"$ref":"#/$defs/A"}"##.into(),r##"{"$dynamicAnchor":"a","$dynamicRef":"#a"}"##.into()] {let p=plan(&schema,&[]);let c=Stop{n:AtomicUsize::new(0),at:usize::MAX};let mut r=run(&p,&c);let ctx=r.empty_context.clone();r.alias(p.entry,&ctx).unwrap();let count=c.n.load(Relaxed);drop(r);for at in 0..count{let c=Stop{n:AtomicUsize::new(0),at};let snapshot=crate::review_allocations::start();let mut r=run(&p,&c);let ctx=r.empty_context.clone();let e=r.alias(p.entry,&ctx).unwrap_err();assert_eq!(e.reason,NoVerdictReason::Cancelled);assert_eq!(r.alias_path.len(),0,"at{at}");assert_eq!(c.n.load(Relaxed),at+1);let fresh=AtomicBool::new(false);r.graph=Graph::new(48<<20,None,64,&fresh);assert!(r.alias(p.entry,&ctx).is_ok());assert_eq!(r.alias_path.len(),0);drop(r);drop(ctx);drop(e);let m=crate::review_allocations::finish(snapshot,1);assert_eq!(m["baseline_live_bytes"],m["ending_live_bytes"]);}
 let c=AtomicBool::new(false);let mut base=run(&p,&c);let ctx=base.empty_context.clone();let before=base.graph.remaining();base.alias(p.entry,&ctx).unwrap();let used=before.bytes-base.graph.remaining().bytes;
 for bytes in 0..=used {let mut r=run(&p,&c);r.graph=Graph::new(bytes,None,64,&c);let result=r.alias(p.entry,&ctx);assert_eq!(r.alias_path.len(),0);if bytes<used {assert_eq!(result.unwrap_err().reason,NoVerdictReason::LimitExceeded);}else{assert!(result.is_ok());}}
 for work in 0..count {let mut r=run(&p,&c);r.graph=Graph::new(48<<20,Some(work),64,&c);let _=r.alias(p.entry,&ctx);assert_eq!(r.alias_path.len(),0);}
 println!("alias-checkpoints={count} reservation={used}");}}
#[test] fn semantic_exact_v2_v9(){for (v,e) in [("[0,1,2]","S"),("[0,1,1.0]","F"),("[9007199254740992,9007199254740993]","S"),("[1e400,10e399]","F"),(r#"["a","\u0061"]"#,"F"),(r#"["😀","\ud83d\ude00"]"#,"F"),(r#"["\ud800","\ud800"]"#,"F"),(r#"["\ud800","\\ud800"]"#,"S"),(r#"[{"a":1,"b":2},{"b":2.0,"a":1.0}]"#,"F"),("[[1,2],[2,1]]","S"),(r#"[{},[],{"a":"a"},["a","a"]]"#,"S")] {check(r#"{"uniqueItems":true}"#,v,e);}
 for (s,v,e)in[(r#"{"const":{"a":[1,{"b":"x"}]}}"#,r#"{"a":[1.0,{"b":"\u0078"}]}"#,"S"),(r#"{"const":{"a":[1,{"b":"x"}]}}"#,r#"{"a":[1,{"b":"y"}]}"#,"F"),(r#"{"enum":[{"a":1},{"a":2}]}"#,r#"{"a":2.0}"#,"S")]{check(s,v,e);}
 let correlated=r##"{"$defs":{"bad":{"$ref":"%"}},"anyOf":[{"prefixItems":[{"$ref":"#/$defs/bad"},true]},{"prefixItems":[true,{"not":{"$ref":"#/$defs/bad"}}]}]}"##;
 check(correlated,"[1,1.0]","S");check(correlated,"[1,2]","U");
 // One malformed original predicate and its negation on equal subjects is a tautology.
 check(r##"{"$defs":{"bad":{"$ref":"%"}},"anyOf":[{"$ref":"#/$defs/bad"},{"not":{"$ref":"#/$defs/bad"}}]}"##,"1","S");
 check(r##"{"$defs":{"A":{"anyOf":[{"type":"integer"},{"type":"array","items":{"$ref":"#/$defs/A"}}]}},"$ref":"#/$defs/A"}"##,"[[1],[1]]","S");
}
